0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2};

#define ROR(x,n) (((x)>>(n))|((x)<<(32-(n))))

/* 4 independent messages hashed simultaneously with AVX2 */
static void sha256_x4(const uint8_t *m0, const uint8_t *m1, const uint8_t *m2, const uint8_t *m3,
                       size_t nblocks, uint32_t h[4][8]){
    __m128i a = _mm_set1_epi32(0x6a09e667);
    __m128i b = _mm_set1_epi32(0xbb67ae85);
    __m128i c = _mm_set1_epi32(0x3c6ef372);
    __m128i d = _mm_set1_epi32(0xa54ff53a);
    __m128i e = _mm_set1_epi32(0x510e527f);
    __m128i f = _mm_set1_epi32(0x9b05688c);
    __m128i g = _mm_set1_epi32(0x1f83d9ab);
    __m128i hh= _mm_set1_epi32(0x5be0cd19);
    const __m128i *p0=(const __m128i*)m0,*p1=(const __m128i*)m1,*p2=(const __m128i*)m2,*p3=(const __m128i*)m3;
    for(size_t blk=0; blk<nblocks; blk++){
        __m128i w[64];
        /* load 16 words from each lane, byte-swap, interleave into 16 x __m128i (one word across 4 lanes) */
        __m128i r0 = _mm_loadu_si128(p0+blk*4);
        __m128i r1 = _mm_loadu_si128(p0+blk*4+1);
        __m128i r2 = _mm_loadu_si128(p0+blk*4+2);
        __m128i r3 = _mm_loadu_si128(p0+blk*4+3);
        __m128i s0 = _mm_loadu_si128(p1+blk*4);
        __m128i s1 = _mm_loadu_si128(p1+blk*4+1);
        __m128i s2 = _mm_loadu_si128(p1+blk*4+2);
        __m128i s3 = _mm_loadu_si128(p1+blk*4+3);
        __m128i t0 = _mm_loadu_si128(p2+blk*4);
        __m128i t1 = _mm_loadu_si128(p2+blk*4+1);
        __m128i t2 = _mm_loadu_si128(p2+blk*4+2);
        __m128i t3 = _mm_loadu_si128(p2+blk*4+3);
        __m128i u0 = _mm_loadu_si128(p3+blk*4);
        __m128i u1 = _mm_loadu_si128(p3+blk*4+1);
        __m128i u2 = _mm_loadu_si128(p3+blk*4+2);
        __m128i u3 = _mm_loadu_si128(p3+blk*4+3);
        __m128i mask = _mm_set_epi8(12,13,14,15, 8,9,10,11, 4,5,6,7, 0,1,2,3);
        r0=_mm_shuffle_epi8(r0,mask); r1=_mm_shuffle_epi8(r1,mask); r2=_mm_shuffle_epi8(r2,mask); r3=_mm_shuffle_epi8(r3,mask);
        s0=_mm_shuffle_epi8(s0,mask); s1=_mm_shuffle_epi8(s1,mask); s2=_mm_shuffle_epi8(s2,mask); s3=_mm_shuffle_epi8(s3,mask);
