        u0=_mm_shuffle_epi8(u0,mask); u1=_mm_shuffle_epi8(u1,mask); u2=_mm_shuffle_epi8(u2,mask); u3=_mm_shuffle_epi8(u3,mask);
        /* transpose 4x4 blocks of 32-bit words so lane i holds message i */
        #define TRANSPOSE(A,B,C,D) do{ \
            __m128i _t0=_mm_unpacklo_epi32(A,B), _t1=_mm_unpackhi_epi32(A,B); \
            __m128i _t2=_mm_unpacklo_epi32(C,D), _t3=_mm_unpackhi_epi32(C,D); \
