    #undef STORE
}

int main(){
    size_t n = (20000ull*1024) & ~63ull; /* multiple of 64 for this microbench */
    size_t nblocks = n/64;
    uint8_t *data = aligned_alloc(64, n*4);
    memset(data, 0x5a, n*4);
    uint32_t h[4][8];
    int reps=3;
    struct timespec a,b;
    clock_gettime(CLOCK_MONOTONIC,&a);
    for(int i=0;i<reps;i++) sha256_x4(data, data+n, data+2*n, data+3*n, nblocks, h);
    clock_gettime(CLOCK_MONOTONIC,&b);
    double t = (b.tv_sec-a.tv_sec)+(b.tv_nsec-a.tv_nsec)/1e9;
    double mb = (double)n*4*reps/1e6;
    printf("x4 throughput %.1f MB/s  (%.4f s for %.0f MB)\n", mb/t, t, mb);

    uint8_t out[32];
    clock_gettime(CLOCK_MONOTONIC,&a);
    size_t total=0;
    while(total < (size_t)(n*4*reps)){ SHA256(data, n, out); total+=n; }
    clock_gettime(CLOCK_MONOTONIC,&b);
    t = (b.tv_sec-a.tv_sec)+(b.tv_nsec-a.tv_nsec)/1e9;
    printf("openssl SHA256 %.1f MB/s\n", (double)total/1e6/t);

    /* verify one block against openssl */
    uint8_t blk[64]; memset(blk,0x11,64);
    uint8_t ref[32]; SHA256(blk,64,ref);
    uint32_t hh[4][8];
    sha256_x4(blk,blk,blk,blk,1,hh);
    uint8_t got[32];
    for(int i=0;i<8;i++){ got[4*i]=hh[0][i]>>24; got[4*i+1]=hh[0][i]>>16; got[4*i+2]=hh[0][i]>>8; got[4*i+3]=hh[0][i]; }
    printf("match %d\n", memcmp(ref,got,32)==0);
    return 0;
}
