/* 8-way interleaved AVX2 SHA-256 with Merkle-Damgard padding.
   sha256_x8 hashes 8 independent messages of equal byte length. */
#include <stdint.h>
#include <string.h>
#include <stdlib.h>
#include <immintrin.h>

static const uint32_t K[64] = {
0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
