static inline __m256i ROR(__m256i x, int n){
    return _mm256_or_si256(_mm256_srli_epi32(x, n), _mm256_slli_epi32(x, 32-n));
}

/* Process nblocks full 64-byte blocks per lane. state[8] holds running hash (lane-major via ymm). */
static void compress_x8(const uint8_t *m[8], size_t nblocks, __m256i state[8]){
    __m256i a=state[0],b=state[1],c=state[2],d=state[3];
    __m256i e=state[4],f=state[5],g=state[6],h=state[7];
    const __m256i bswap = _mm256_set_epi8(
        12,13,14,15,8,9,10,11,4,5,6,7,0,1,2,3,
        12,13,14,15,8,9,10,11,4,5,6,7,0,1,2,3);
    for(size_t blk=0; blk<nblocks; blk++){
        __m256i w[64];
        __m256i rows[8], rows2[8];
        for(int lane=0; lane<8; lane++){
            rows[lane]  = _mm256_shuffle_epi8(_mm256_loadu_si256((const __m256i*)(m[lane]+blk*64)), bswap);
            rows2[lane] = _mm256_shuffle_epi8(_mm256_loadu_si256((const __m256i*)(m[lane]+blk*64+32)), bswap);
        }
        #define T8(RR,base) do{ \
            __m256i t0=_mm256_unpacklo_epi32(RR[0],RR[1]), t1=_mm256_unpackhi_epi32(RR[0],RR[1]); \
            __m256i t2=_mm256_unpacklo_epi32(RR[2],RR[3]), t3=_mm256_unpackhi_epi32(RR[2],RR[3]); \
            __m256i t4=_mm256_unpacklo_epi32(RR[4],RR[5]), t5=_mm256_unpackhi_epi32(RR[4],RR[5]); \
            __m256i t6=_mm256_unpacklo_epi32(RR[6],RR[7]), t7=_mm256_unpackhi_epi32(RR[6],RR[7]); \
            __m256i u0=_mm256_unpacklo_epi64(t0,t2), u1=_mm256_unpackhi_epi64(t0,t2); \
            __m256i u2=_mm256_unpacklo_epi64(t1,t3), u3=_mm256_unpackhi_epi64(t1,t3); \
            __m256i u4=_mm256_unpacklo_epi64(t4,t6), u5=_mm256_unpackhi_epi64(t4,t6); \
            __m256i u6=_mm256_unpacklo_epi64(t5,t7), u7=_mm256_unpackhi_epi64(t5,t7); \
            w[base+0]=_mm256_permute2x128_si256(u0,u4,0x20); w[base+4]=_mm256_permute2x128_si256(u0,u4,0x31); \
            w[base+1]=_mm256_permute2x128_si256(u1,u5,0x20); w[base+5]=_mm256_permute2x128_si256(u1,u5,0x31); \
            w[base+2]=_mm256_permute2x128_si256(u2,u6,0x20); w[base+6]=_mm256_permute2x128_si256(u2,u6,0x31); \
            w[base+3]=_mm256_permute2x128_si256(u3,u7,0x20); w[base+7]=_mm256_permute2x128_si256(u3,u7,0x31); \
        }while(0)
        T8(rows,0); T8(rows2,8);
        #undef T8
        for(int i=16;i<64;i++){
            __m256i s0=_mm256_xor_si256(_mm256_xor_si256(ROR(w[i-15],7),ROR(w[i-15],18)),_mm256_srli_epi32(w[i-15],3));
            __m256i s1=_mm256_xor_si256(_mm256_xor_si256(ROR(w[i-2],17),ROR(w[i-2],19)),_mm256_srli_epi32(w[i-2],10));
            w[i]=_mm256_add_epi32(_mm256_add_epi32(w[i-16],s0),_mm256_add_epi32(w[i-7],s1));
        }
        __m256i A=a,B=b,C=c,D=d,E=e,F=f,G=g,H=h;
        for(int i=0;i<64;i++){
            __m256i S1=_mm256_xor_si256(_mm256_xor_si256(ROR(E,6),ROR(E,11)),ROR(E,25));
            __m256i ch=_mm256_xor_si256(_mm256_and_si256(E,F),_mm256_andnot_si256(E,G));
            __m256i t1=_mm256_add_epi32(H,_mm256_add_epi32(S1,_mm256_add_epi32(ch,_mm256_add_epi32(_mm256_set1_epi32(K[i]),w[i]))));
            __m256i S0=_mm256_xor_si256(_mm256_xor_si256(ROR(A,2),ROR(A,13)),ROR(A,22));
            __m256i maj=_mm256_xor_si256(_mm256_xor_si256(_mm256_and_si256(A,B),_mm256_and_si256(A,C)),_mm256_and_si256(B,C));
            __m256i t2=_mm256_add_epi32(S0,maj);
            H=G;G=F;F=E;E=_mm256_add_epi32(D,t1);D=C;C=B;B=A;A=_mm256_add_epi32(t1,t2);
        }
        a=_mm256_add_epi32(a,A);b=_mm256_add_epi32(b,B);c=_mm256_add_epi32(c,C);d=_mm256_add_epi32(d,D);
        e=_mm256_add_epi32(e,E);f=_mm256_add_epi32(f,F);g=_mm256_add_epi32(g,G);h=_mm256_add_epi32(h,H);
    }
    state[0]=a;state[1]=b;state[2]=c;state[3]=d;state[4]=e;state[5]=f;state[6]=g;state[7]=h;
}

/* Hash 8 messages, each of exactly `len` bytes. out[lane] gets 32 bytes. */
void sha256_x8(const uint8_t *data[8], size_t len, uint8_t out[8][32]){
    size_t full = len / 64;
    size_t rem = len % 64;
    __m256i state[8];
    state[0]=_mm256_set1_epi32(0x6a09e667); state[1]=_mm256_set1_epi32(0xbb67ae85);
    state[2]=_mm256_set1_epi32(0x3c6ef372); state[3]=_mm256_set1_epi32(0xa54ff53a);
    state[4]=_mm256_set1_epi32(0x510e527f); state[5]=_mm256_set1_epi32(0x9b05688c);
    state[6]=_mm256_set1_epi32(0x1f83d9ab); state[7]=_mm256_set1_epi32(0x5be0cd19);
    if(full) compress_x8(data, full, state);

    /* padding: 0x80, zeros, 64-bit big-endian bit length. 1 or 2 extra blocks. */
    uint8_t tail[8][128];
    size_t bitlen = len * 8;
    size_t tailblocks;
    for(int lane=0; lane<8; lane++){
        memset(tail[lane], 0, 128);
        if(rem) memcpy(tail[lane], data[lane] + full*64, rem);
        tail[lane][rem] = 0x80;
        size_t lenpos;
        if(rem < 56){ tailblocks = 1; lenpos = 56; }
        else { tailblocks = 2; lenpos = 120; }
        for(int i=0;i<8;i++) tail[lane][lenpos+7-i] = (uint8_t)(bitlen >> (8*i));
    }
    const uint8_t *tp[8];
    for(int lane=0; lane<8; lane++) tp[lane] = tail[lane];
    compress_x8(tp, tailblocks, state);

    uint32_t tmp[8];
    for(int i=0;i<8;i++){
        _mm256_storeu_si256((__m256i*)tmp, state[i]);
        for(int lane=0; lane<8; lane++){
            uint32_t v = tmp[lane];
            out[lane][4*i]   = (uint8_t)(v>>24);
            out[lane][4*i+1] = (uint8_t)(v>>16);
            out[lane][4*i+2] = (uint8_t)(v>>8);
            out[lane][4*i+3] = (uint8_t)v;
        }
    }
}
