void sha256_x8(const uint8_t *data[8], size_t len, uint8_t out[8][32]);

/* Split data into 8 equal lanes (caller guarantees len%8==0), hash each, concatenate. */
void sha256_split8(const uint8_t *data, size_t len, uint8_t out[256]){
