static void sha256_ni(const uint8_t *data, size_t len, uint8_t out[32]){
    uint32_t state[8] = {0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19};
    size_t full = len & ~((size_t)63);
    if(full) sha256_ni_blocks(state, data, full);
    uint8_t tail[128];
    size_t rem = len - full;
    memset(tail, 0, 128);
    if(rem) memcpy(tail, data+full, rem);
    tail[rem] = 0x80;
    size_t blocks = (rem < 56) ? 1 : 2;
    size_t bitlen = len*8;
    size_t lenpos = (blocks==1)?56:120;
    for(int i=0;i<8;i++) tail[lenpos+7-i] = (uint8_t)(bitlen>>(8*i));
    sha256_ni_blocks(state, tail, blocks*64);
    for(int i=0;i<8;i++){ out[4*i]=state[i]>>24; out[4*i+1]=state[i]>>16; out[4*i+2]=state[i]>>8; out[4*i+3]=state[i]; }
}

