    int reps=5; struct timespec a,c; clock_gettime(CLOCK_MONOTONIC,&a);
    for(int i=0;i<reps;i++) sha256_ni(b,len,out);
    clock_gettime(CLOCK_MONOTONIC,&c);
    double tt=(c.tv_sec-a.tv_sec)+(c.tv_nsec-a.tv_nsec)/1e9;
    printf("SHA-NI %.1f MB/s\n", (double)len*reps/1e6/tt);
    return 0;
}
