import hashlib, random
def tree_hash(data, k):
    n=len(data); ln=n//k
    leaves=[]
    for i in range(k):
        s=i*ln; e=n if i==k-1 else s+ln
        leaves.append(hashlib.sha256(data[s:e]).digest())
    level=leaves
    while len(level)>1:
        nxt=[]
        for i in range(0,len(level),2):
            nxt.append(hashlib.sha256(level[i]+level[i+1]).digest())
        level=nxt
    return level[0]
random.seed(0)
