import hashlib
from concurrent.futures import ThreadPoolExecutor

_POOL = ThreadPoolExecutor(max_workers=8)
_K = 8

def _worker(args):
    data, start, length = args
    return hashlib.sha256(data[start:start + length]).digest()

class Solver:
    def solve(self, problem, **kwargs):
        data = problem["plaintext"]
        n = len(data)
        k = _K
        ln = n // k
        jobs = [(data, i * ln, ln if i < k - 1 else n - i * ln) for i in range(k)]
        parts = list(_POOL.map(_worker, jobs))
        return {"digest": hashlib.sha256(b"".join(parts)).digest()}
