#include <stdint.h>
#include <string.h>
#include <pthread.h>
void sha256_x8(const uint8_t *data[8], size_t len, uint8_t out[8][32]);

typedef struct { const uint8_t *base; size_t ln; uint8_t *out; } mtjob;
static void *worker(void *arg){
    mtjob *j = arg;
    const uint8_t *m[8];
    for(int i=0;i<8;i++) m[i] = j->base + i*j->ln;
    sha256_x8(m, j->ln, (uint8_t (*)[32])j->out);
    return NULL;
}

/* Split into `groups` groups of 8 lanes (groups threads). len must be divisible by 8*groups. */
void sha256_split_mt(const uint8_t *data, size_t len, int groups, uint8_t *out){
    size_t per = len / groups;
    size_t ln = per / 8;
    pthread_t th[16];
    mtjob jobs[16];
    for(int g=0; g<groups; g++){
        jobs[g].base = data + g*per;
        jobs[g].ln = ln;
        jobs[g].out = out + g*256;
        pthread_create(&th[g], NULL, worker, &jobs[g]);
    }
    for(int g=0; g<groups; g++) pthread_join(th[g], NULL);
}
