import os, time, hashlib
from concurrent.futures import ProcessPoolExecutor
from cryptography.hazmat.primitives import hashes

def worker(data):
    return hashlib.sha256(data).digest()

def cref(d):
    h = hashes.Hash(hashes.SHA256()); h.update(d); return h.finalize()

def main():
    data = os.urandom(20000*1024)
    k = 8
    n = len(data); ln = n//k
    parts = [data[i*ln:(i+1)*ln] for i in range(k-1)] + [data[(k-1)*ln:]]
    with ProcessPoolExecutor(max_workers=k) as pool:
        pool.map(worker, parts)  # warmup
        for _ in range(1): cref(data)
        N=3
        t0=time.perf_counter()
        for _ in range(N): cref(data)
        t1=time.perf_counter()
        for _ in range(N):
            res = list(pool.map(worker, parts))
            hashlib.sha256(b''.join(res)).digest()
        t2=time.perf_counter()
        print('crypto %.4f proc %.4f speedup %.2f'%((t1-t0)/N,(t2-t1)/N,(t1-t0)/(t2-t1)))

if __name__ == '__main__':
    main()
